compositions.css:
.essay { height: 100%; padding: 36px 43px; background: #f2e8d3; color: #28231e; box-shadow: 0 28px 55px #0005; }
span { font: 700 12px system-ui; letter-spacing: .15em; color: #744435; }
h1 { font: 500 84px/.9 Georgia, serif; letter-spacing: -.07em; margin: 16px 0; }
p { font: 24px/1.34 Georgia, serif; margin: 0; }
.intro { font-size: 27px; line-height: 1.22; max-width: 605px; border-bottom: 1px solid #aa8d76; padding-bottom: 20px; }
.columns { display: grid; grid-template-columns: 1fr; gap: 16px; margin-top: 16px; }
h2 { font: 700 25px Georgia, serif; margin: 0 0 7px; }
footer { margin-top: 17px; font: 13px system-ui; color: #744435; }

.margin { border-radius: 0 13px 13px 0; border-left: 6px solid #d3a790; background: #48323a; color: #f7e6dc; height: 100%; padding: 34px; }
span { font-size: 12px; letter-spacing: .15em; color: #eccbb5; }
h2 { font: 500 44px Georgia, serif; letter-spacing: -.04em; margin: 12px 0; }
ol { padding-left: 22px; font-size: 18px; line-height: 1.55; }
blockquote { font: italic 22px/1.3 Georgia, serif; padding-top: 14px; border-top: 1px solid #b88b81; margin: 0; }
